/* PG_SITE_CATALOG_APPEND */
function pgApplyCatalog(lang){
  var dict=PG_SITE_CATALOG[lang]||{}, items=dict.t||{}, cats=dict.c||{};
  var templateLabel=(T[lang]&&T[lang].ftTpl)||T.EN.ftTpl||"Templates";
  document.querySelectorAll("#template-categories .featured-template-card").forEach(function(card){
    var title=card.querySelector("h3"),detail=card.querySelector("p");
    if(!title)return;
    var key=title.getAttribute("data-pg-source-title")||title.textContent.trim();
    title.setAttribute("data-pg-source-title",key);
    if(detail&&!detail.hasAttribute("data-pg-source-desc"))detail.setAttribute("data-pg-source-desc",detail.textContent);
    var val=items[key]||[];
    title.textContent=lang==="EN"?key:(val[0]||key);
    if(detail)detail.textContent=lang==="EN"?detail.getAttribute("data-pg-source-desc"):(val[1]||detail.getAttribute("data-pg-source-desc"));
  });
  document.querySelectorAll("#template-categories .category-name, #template-categories .featured-template-category > span:not(.featured-template-icon):not(.pro-template-badge)").forEach(function(el){
    var key=el.getAttribute("data-pg-source-category")||el.textContent.trim();
    el.setAttribute("data-pg-source-category",key);
    el.textContent=lang==="EN"?key:(cats[key]||key);
  });
  document.querySelectorAll("#template-categories .category-number").forEach(function(el){
    var key=el.getAttribute("data-pg-source-count")||el.textContent.trim();
    el.setAttribute("data-pg-source-count",key);
    var m=key.match(/^(\d+) templates$/i);
    el.textContent=lang==="EN"||!m?key:(m[1]+" "+templateLabel);
  });
  var count=document.querySelector("#template-categories .category-count-total span");
  if(count)count.textContent=templateLabel;
}


// Localize legacy leaf labels whose English copy already matches an existing
// translated key, without rewriting interactive device demos or API examples.
var PG_LOOSE_ENGLISH = null;
function pgApplyLoose(lang){
  if(!PG_LOOSE_ENGLISH){
    PG_LOOSE_ENGLISH=Object.create(null);
    Object.keys(T.EN).forEach(function(k){
      var v=T.EN[k];
      if(typeof v!=="string"||/[<>]/.test(v))return;
      var norm=v.replace(/\s+/g," ").trim();
      if(norm.length>1 && norm!=="Poly-Glot AI Workspace" && !PG_LOOSE_ENGLISH[norm])PG_LOOSE_ENGLISH[norm]=k;
    });
  }
  var candidates=document.querySelectorAll("nav a, main p, main span, main div, main h2, main h3, main h4, main button, section p, section span, section div, section h2, section h3, section h4, section button, footer a, footer span");
  candidates.forEach(function(el){
    if(el.children.length||el.matches("[data-i18n],[data-i18n-html]"))return;
    if(el.closest("[data-i18n],[data-i18n-html],pre,code,svg,script,style,noscript,textarea,select,#demo,#screenshots,#iphone-duo,#pgChat-widget,.phone-screen,.demo-iphone-frame"))return;
    var key=el.getAttribute("data-pg-loose-key"),orig=el.getAttribute("data-pg-loose-en");
    if(!key){
      orig=el.textContent;
      key=PG_LOOSE_ENGLISH[orig.replace(/\s+/g," ").trim()];
      if(!key)return;
      el.setAttribute("data-pg-loose-en",orig);
      el.setAttribute("data-pg-loose-key",key);
    }
    var translated=lang==="EN"?orig:gt(key,lang);
    if(translated && !/[<>]/.test(translated) && el.textContent!==translated)el.textContent=translated;
  });
}

