// ===== GETTER =====
function gt(k,lang){var duoKey=(lang==="ZH_TW"?"ZH-TW":lang);return(DUO[duoKey]&&DUO[duoKey][k])||(T[lang]&&T[lang][k])||(DUO.EN&&DUO.EN[k])||T.EN[k]||'';}

// ===== GLOBAL STATE =====
var curLang='EN';

// ===== BUILD PICKER =====
function buildPicker(){
if(!document.body)return;
var wrap=document.createElement('div');wrap.id='pgGlobalLangPicker';
var btn=document.createElement('button');btn.type='button';btn.id='pgGlobalLangBtn';
btn.innerHTML='<span id="pgGlobalFlag">\u{1F1FA}\u{1F1F8}</span><span id="pgGlobalCode">EN</span>';
var dd=document.createElement('div');dd.id='pgGlobalLangDD';
wrap.appendChild(btn);document.body.appendChild(dd);
LANGS.forEach(function(L){
var r=document.createElement('div');r.className='pgGlob-row'+(L.code==='EN'?' active':'');
r.setAttribute('data-lang',L.code);
r.innerHTML='<span class="gf">'+L.flag+'</span><span class="gc">'+L.code+'</span>';r.title=L.name;r.setAttribute('aria-label',L.name+' ('+L.code+')');
r.onclick=function(e){e.stopPropagation();setLang(L.code,L.flag);};
dd.appendChild(r);
});
btn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();var opening=!dd.classList.contains('open');dd.classList.toggle('open');if(opening){var r=btn.getBoundingClientRect();dd.style.left=Math.max(8,r.left)+'px';dd.style.top=(r.bottom+6)+'px';setTimeout(function(){var a=dd.querySelector('.pgGlob-row.active');if(a)a.scrollIntoView({block:'center'});},0);}});
document.addEventListener('click',function(e){if(!wrap.contains(e.target)&&!dd.contains(e.target))dd.classList.remove('open');});
var slot=document.getElementById('pgLangSlot');
if(slot){slot.appendChild(wrap);}else{var navBrand=document.querySelector('.nav-brand');if(navBrand&&navBrand.parentNode){navBrand.parentNode.insertBefore(wrap,navBrand.nextSibling);}else{document.body.appendChild(wrap);}}
}

// ===== SET LANGUAGE =====
function setLang(code,flag){
curLang=code;
var rtl=(code==="AR"||code==="HE");
document.documentElement.setAttribute("lang",code==="ZH_TW"?"zh-Hant":code.toLowerCase().replace("_","-"));
document.documentElement.setAttribute("dir","ltr");
document.documentElement.setAttribute("data-pg-rtl",rtl?"true":"false");
if(document.body)document.body.setAttribute("dir","ltr");
var gf=document.getElementById('pgGlobalFlag'),gc=document.getElementById('pgGlobalCode');
if(gf)gf.textContent=flag;if(gc)gc.textContent=code;
document.querySelectorAll('.pgGlob-row').forEach(function(r){r.classList.toggle('active',r.getAttribute('data-lang')===code);});
var dd=document.getElementById('pgGlobalLangDD');if(dd)dd.classList.remove('open');
var cf=document.getElementById('pgChat-lang-flag');if(cf)cf.textContent=flag;
applyAll(code);
updateChat(code);
try{window.dispatchEvent(new CustomEvent('pg:languagechange',{detail:{code:code,flag:flag}}));}catch(e){}
/* Keep all live device renders synchronized with the global language.
   i18n.js is the source of truth for the global selector, so retry after
   dependent device-localization scripts finish loading. */
(function syncDeviceSurfaces(selectedCode){
  var tries=0;
  function run(){
    tries++;
    try{
      if(window._pgDeviceUI&&typeof window._pgDeviceUI.apply==='function'){
        window._pgDeviceUI.apply(selectedCode);
      }
      if(typeof window._pgGlobalDeviceSyncV6==='function'){
        window._pgGlobalDeviceSyncV6();
      }
      if(typeof window.__pgSiteLocalizeAllVisible==='function'){
        window.__pgSiteLocalizeAllVisible();
      }
      if(typeof window.__polyglotSiteDeviceLocalizeAllVisible==='function'){
        window.__polyglotSiteDeviceLocalizeAllVisible();
      }
    }catch(e){}
    if(tries<10)setTimeout(run,tries<4?60:180);
  }
  run();
})(code);
try{localStorage.setItem('pgLang',code);}catch(e){}
}

// ===== APPLY TO ALL SITE ELEMENTS =====
function applyAll(lang){
document.querySelectorAll('[data-i18n]').forEach(function(el){
var k=el.getAttribute('data-i18n'),v=gt(k,lang);
if(v){
var toggle=el.querySelector('.toggle');
var ck=el.querySelector('.ck,.check');
if(el.tagName==='A'&&el.getAttribute('href')){
el.textContent=v;
}else{
el.textContent=v;
}
if(toggle)el.appendChild(toggle);
if(ck){el.insertBefore(ck,el.firstChild);el.insertBefore(document.createTextNode(' '),ck.nextSibling);}
}
});
// HTML-rich translations (supports <br>, <strong>, <span> etc.)
document.querySelectorAll('[data-i18n-html]').forEach(function(el){
var k=el.getAttribute('data-i18n-html'),v=gt(k,lang);
if(v){el.innerHTML=v;}
});
pgApplyCatalog(lang);
pgApplyLoose(lang);
}

// ===== UPDATE CHAT WIDGET =====
function updateChat(lang){
var t1=document.querySelector('#pgChat-header-left div div:first-child');
var t2=document.querySelector('#pgChat-header-left div div:last-child');
if(t1)t1.textContent=gt('chatT',lang);
if(t2)t2.textContent=gt('chatSub',lang);
var inp=document.getElementById('pgChat-input');
if(inp)inp.placeholder=gt('chatPH',lang);
window._pgChatLang=lang;

// === LOCALIZE TOPICS DROPDOWN ===
if(window._pgChatI18n){
var sel=document.getElementById('pgChat-topics-select');
if(sel){
var tops=window._pgChatI18n.getTopics(lang);
var opts=sel.querySelectorAll('option');
// Map option index to topic key (same order as HTML)
var topicKeys=['_browse','_whatIs','_pricing','_whichAIs','_howWorks','_freePlan','_trial','_afterTrial','_compare','_templates','_categories','_languages','_appLang','_outputLang','_voice','_devices','_crossDevice','_privacy','_download','_cancel','_mcp','_mcpSetup','_features','_sending','_history','_custom','_offline','_web','_whoMade','_children','_api','_autoFill','_payment','_promptStudio','_support','_different','_disclaimer'];
for(var i=0;i<opts.length&&i<topicKeys.length;i++){
var topicText=tops[topicKeys[i]]||(window._pgChatI18n.TOPICS.EN&&window._pgChatI18n.TOPICS.EN[topicKeys[i]]);if(topicText)opts[i].textContent=topicText;
}
}
// === LOCALIZE BUBBLE + CLEAR TITLES ===
var titles=window._pgChatI18n.getTitles(lang);
var bubble=document.getElementById('pgChat-bubble');
if(bubble&&titles.bubble)bubble.title=titles.bubble;
var clearBtn=document.getElementById('pgChat-clear');
if(clearBtn&&titles.clear)clearBtn.title=titles.clear;
}

// Re-render welcome message + suggestion buttons if chat is showing welcome state
if(typeof window.pgChat!=='undefined'&&typeof window.pgChat.renderWelcome==='function'){
// Only re-render if no user messages yet (welcome state)
var msgs=document.getElementById('pgChat-messages');
if(msgs){
var userMsgs=msgs.querySelectorAll('.pgChat-msg.user');
if(!userMsgs||userMsgs.length===0){
window.pgChat.renderWelcome();
}
}
}
}

// ===== TAG NAV (only elements without data-i18n in HTML) =====
function tagAll(){
var navKeys={'#screenshots':'navSS','#features':'navFeat','#apps':'sc2Tag','#demo':'navDemo','#pricing':'navPrice1','#faq':'navFAQ','#knowledge-center':'navGuides','#connect':'navConnect'};
document.querySelectorAll('nav.nav ul.nav-links li a').forEach(function(a){
  var key=navKeys[a.getAttribute('href')];
  if(key)a.setAttribute('data-i18n',key);
});
var navCTA=document.querySelector('nav.nav .nav-cta a');
if(navCTA&&!navCTA.getAttribute('data-i18n'))navCTA.setAttribute('data-i18n','navCTA');
// All other elements are tagged directly in HTML with data-i18n attributes
}

